fn solve(input: Vec<char>) -> Vec<char> {
    // Get the first two characters as digits
    let first_digit = input[0];
    let second_digit = input[1];
    
    // Define the mapping from digit to good count
    let good_count = |c: char| -> u32 {
        match c {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // This case shouldn't occur per problem constraints
        }
    };
    
    // Calculate the product
    let product = good_count(first_digit) * good_count(second_digit);
    
    // Convert product to string and add newline
    let mut result = product.to_string();
    result.push('\n');
    
    // Convert to Vec<char>
    result.chars().collect()
}